Given two arrays x[] and y[] of points where (x[i], y[i]) represents a point on the x-y plane. Returns the maximum number of points that lie on the same straight line.Examples: Input: x[] = [1, 2, 3], y[] = [1, 2, 3]Output: 3Explanation: The points in straight line are- (1, 1), (2, 2) and (3, 3).Input: x[] = [1, 3, 5, 4, 2, 1], y[] = [1, 2, 3, 1, 3, 4]Output: 4Explanation: The points in straight line are- (3, 2),(4, 1),(2, 3),(1, 4)Try It YourselfTable of Content[Naive Approach] Brute Force Line Check - O(n³) Time and O(1) Space[Expected Approach] Slope Hashing - O(n²) Time and O(n) Space[Naive Approach] Brute Force Line Check - O(n³) Time and O(1) SpacePick every pair of points to form a line, then count how many points lie on that line using cross product. Track maximum count across all pairs.If n ≤ 2, return nInitialize ans = 1For each pair (i, j), skip if points are identicalFor every other point k, check collinearity using cross productIf (y[j] - y[i]) × (x[k] - x[i]) equals (y[k] - y[i]) × (x[j] - x[i]), increment countUpdate ans with maximum countReturn ans
            C++

    #include <iostream>
#include <vector>
using namespace std;

int maxPoints(vector<int>& x, vector<int>& y) {
    int n = x.size();

    // If there are 2 or fewer points, 
    // return the number of points
    if (n <= 2)
        return n;

    int ans = 1;

    // Iterate through each pair of points
    for (int i = 0; i < n; i++) {

        for (int j = i + 1; j < n; j++) {

            // Skip identical points
            if (x[i] == x[j] && y[i] == y[j])
                continue;

            int cnt = 0;

            // Check other points to see if they lie on the same line
            for (int k = 0; k < n; k++) {

                long long lhs =
                    1LL * (y[j] - y[i]) * (x[k] - x[i]);

                long long rhs =
                    1LL * (y[k] - y[i]) * (x[j] - x[i]);

                if (lhs == rhs)
                    cnt++;
            }

            // Update the maximum number of points on a line
            ans = max(ans, cnt);
        }
    }

    return ans;
}

int main()
{
    vector<int> x = {-1, 0, 1, 2, 3, 3};
    vector<int> y = {1, 0, 1, 2, 3, 4};

    cout << maxPoints(x, y) << endl;

    return 0;
}


