{
    int n = x.size();

    if (n < 2)
        return n;

    int maxPoint = 0;
    int curMax, overlapPoints, verticalPoints;

    // Stores frequency of each slope
    unordered_map<string, int> slopeMap;

    // looping for each point
    for (int i = 0; i < n; i++)
    {
        curMax = overlapPoints = verticalPoints = 0;

        // looping from i + 1 to ignore same pair again
        for (int j = i + 1; j < n; j++)
        {
            // If both point are equal then just
            // increase overlapPoint count
            if (x[i] == x[j] && y[i] == y[j])
                overlapPoints++;

            // If x co-ordinate is same, then both
            // point are vertical to each other
            else if (x[i] == x[j])
                verticalPoints++;

            else
            {
                int yDif = y[j] - y[i];
                int xDif = x[j] - x[i];

                int g = __gcd(abs(xDif), abs(yDif));

                // reducing the difference by their gcd
                yDif /= g;
                xDif /= g;

                if (xDif < 0)
                {
                    xDif *= -1;
                    yDif *= -1;
                }

                string slope = to_string(yDif) + "#" + to_string(xDif);

                // increasing the frequency of current slope
                // in map
                slopeMap[slope]++;
                curMax = max(curMax, slopeMap[slope]);
            }

            curMax = max(curMax, verticalPoints);
        }

        // updating global maximum by current point's maximum
        maxPoint = max(maxPoint,
                       curMax + overlapPoints + 1);

        slopeMap.clear();
    }

    return maxPoint;
}

